325:       session.message = actual ? `${memberName(user)} restored ${actual} HP!` : 'But it failed!';
326:     }
327:     for (const [stat, amount] of Object.entries(move.self || {})) changeStage(session, user, stat, amount);
328:     for (const [stat, amount] of Object.entries(move.foe || {})) changeStage(session, target, stat, amount);
329:     if (move.eff && (move.cat === 'status' || !hit || hit.damage > 0) && Math.random() * 100 < number(move.eff.chance, 100)) {
330:       if (move.eff.status) updateStatus(session, move.eff.target === 'self' ? user : target, move.eff.status);
331:       if (move.eff.stat) changeStage(session, move.eff.target === 'self' ? user : target, move.eff.stat, number(move.eff.stages, -1));
332:     }
