334:   function calculateDamage(user, target, move) {
335:     if (!move || !move.power) return { damage:0, effectiveness:1, critical:false };
336:     const def = ability(target), userAbility = ability(user);
337:     const atkStat = move.cat === 'spec' ? 'spa' : 'atk';
338:     const defStat = move.cat === 'spec' ? 'spd' : 'def';
339:     let effectiveness = typeEff(move.type, types(target));
340:     if (def.immune?.includes(move.type)) effectiveness = 0;
341:     if (def.absorb === move.type) return { damage:0, effectiveness:0, absorbed:true, heal:true, critical:false };
342:     let power = move.power;
343:     if (userAbility.pinch === move.type && user.hp <= user.maxHp / 3) power *= 1.5;
344:     if (userAbility.boost && (userAbility.boost.type === move.type || userAbility.boost.type === 'all')) power *= userAbility.boost.mult;
345:     if (def.resist?.[move.type]) effectiveness *= def.resist[move.type];
346:     if (def.multiscale && target.hp === target.maxHp) effectiveness *= .5;
347:     const critChance = .04 * (1 + number(move.crit, 0) + number(userAbility.crit, 0));
348:     const critical = Math.random() < critChance;
349:     const randomFactor = .85 + Math.random() * .15;
350:     const stab = types(user).includes(move.type) ? 1.5 : 1;
351:     const base = Math.floor((((2 * user.level / 5 + 2) * power * statValue(user, atkStat) / statValue(target, defStat)) / 50) + 2);
352:     const damage = effectiveness === 0 ? 0 : Math.max(1, Math.floor(base * effectiveness * stab * (critical ? 1.5 : 1) * randomFactor));
353:     return { damage, effectiveness, critical, absorbed:false };
354:   }
355:   async function performMove(session, user, target, id) {
356:     if (!alive(user) || !alive(target)) return;
357:     const move = validMove(id) || validMove('tackle');
358:     if (user.recharge) { user.recharge = false; await message(session, `${memberName(user)} must recharge!`); return; }
359:     const pp = number(user.pp?.[move.id], move.pp);
360:     if (pp <= 0) { await message(session, `${memberName(user)} has no ${move.name} PP left!`); return; }
361:     user.pp[move.id] = pp - 1;
362:     if (user.status === 'sleep') {
363:       if (Math.random() < .34) user.status = null;
364:       else { await message(session, `${memberName(user)} is fast asleep!`); return; }
365:     }
366:     if (user.status === 'freeze') {
367:       if (Math.random() < .2) user.status = null;
368:       else { await message(session, `${memberName(user)} is frozen solid!`); return; }
369:     }
370:     if (user.status === 'para' && Math.random() < .25) { await message(session, `${memberName(user)} is paralyzed! It can’t move!`); return; }
371:     if (Math.random() * 100 >= number(move.acc, 100)) { await message(session, `${memberName(user)} used ${move.name}, but it missed!`); return; }
372:     const result = calculateDamage(user, target, move);
373:     await message(session, `${memberName(user)} used ${move.name}!`);
374:     if (move.protect) {
375:       user.protected = true;
376:       await message(session, `${memberName(user)} protected itself!`);
377:       return;
378:     }
379:     if (target.protected) { await message(session, `${memberName(target)} protected itself!`); return; }
380:     if (result.absorbed && result.heal) {
381:       target.hp = Math.min(target.maxHp, target.hp + Math.max(1, Math.floor(target.maxHp / 4)));
382:       await message(session, `${memberName(target)} absorbed the attack and restored HP!`); return;
383:     }
384:     if (result.damage > 0) {
385:       let damage = result.damage;
386:       if (ability(target).sturdy && target.hp === target.maxHp && damage >= target.hp) damage = target.hp - 1;
387:       if (ability(target).disguise && !target.disguiseBroken) { target.disguiseBroken = true; damage = 0; await message(session, `${memberName(target)}'s disguise absorbed the hit!`); }
388:       else {
389:         target.hp = Math.max(0, target.hp - damage);
390:         if (result.critical) await message(session, 'A critical hit!');
391:         if (result.effectiveness > 1) await message(session, "It's super effective!");
392:         else if (result.effectiveness > 0 && result.effectiveness < 1) await message(session, "It's not very effective…");
393:         if (move.drain) user.hp = Math.min(user.maxHp, user.hp + Math.max(1, Math.floor(damage * move.drain)));
394:         if (move.recoil) user.hp = Math.max(0, user.hp - Math.max(1, Math.floor(damage * move.recoil)));
395:         if (move.contact) {
396:           const contact = ability(target);
397:           if (contact.contactRecoil) user.hp = Math.max(0, user.hp - Math.max(1, Math.floor(user.maxHp * contact.contactRecoil)));
398:           if (contact.contact && Math.random() * 100 < contact.contact.chance) updateStatus(session, user, contact.contact.status);
399:         }
400:       }
401:       const retaliatory = ability(target).onHitBy;
402:       if (retaliatory?.type === move.type) changeStage(session, target, retaliatory.stat, retaliatory.stages);
403:     }
404:     if (move.recharge) user.recharge = true;
405:     if (move.cat === 'status' || target.hp > 0) applyMoveEffects(session, user, target, move, result);
406:     updateHud(session); render(session);
407:     if (target.hp <= 0) await faint(session, target, user);
408:   }
