/* ============================================================
   POKÉMON ECLIPSE — art engine (terrain)
   Richer procedural pixel art for the overworld.
   ============================================================ */
'use strict';

var Art = globalThis.Art = globalThis.Art || {};

(function () {
  const T = 32;

  function hashStr(s) {
    let h = 2166136261;
    for (let i = 0; i < String(s).length; i++) { h ^= String(s).charCodeAt(i); h = Math.imul(h, 16777619); }
    return h >>> 0;
  }
  function seeded(x, y, s = 0) {
    let n = (Math.imul(x | 0, 374761393) + Math.imul(y | 0, 668265263) + Math.imul(s | 0, 1442695041)) | 0;
    return () => {
      n = Math.imul(n ^ (n >>> 13), 1274126177);
      n = (n ^ (n >>> 16)) >>> 0;
      return n / 4294967296;
    };
  }
  function rgba(hex, a) { const [r, g, b] = hexToRgb(hex); return `rgba(${r},${g},${b},${a})`; }
  function lerp(a, b, t) { return a + (b - a) * t; }
  function centerText(ctx, text, x, y, font, color, align = 'center') {
    ctx.save(); ctx.font = font; ctx.fillStyle = color; ctx.textAlign = align; ctx.textBaseline = 'middle';
    ctx.fillText(text, x, y); ctx.restore();
  }

  const PAL = {
    grass:   { base:'#1f5c3f', dark:'#174a33', light:'#2b7250', hi:'#469b6b', tuft:'#357d54' },
    flower:  { base:'#205f42', dark:'#174a33', light:'#2c7351', hi:'#4aa16f', petals:['#f7a8c8','#ffd875','#e9f2ff','#c9a0ff','#ff9a76'] },
    path:    { base:'#b88954', dark:'#9b6c3d', light:'#d2a466', hi:'#e8c489', pebble:'#85603a' },
    sand:    { base:'#d6b775', dark:'#c3a05d', light:'#eed79b', hi:'#fff0c2', pebble:'#b08c50' },
    rock:    { base:'#525d6e', dark:'#3e4858', light:'#687487', hi:'#7f8da1', moss:'#4b795a' },
    cave:    { base:'#262c45', dark:'#1c2136', light:'#343b58', hi:'#454e70', glow:'#63d8ff' },
    caveP:   { base:'#4a4560', dark:'#35314a', light:'#5d5778', hi:'#746c92', line:'#272337' },
    snow:    { base:'#dcecf5', dark:'#c3d9e6', light:'#eefaff', hi:'#ffffff', shadow:'#a8c6d8' },
    water:   { base:'#1c6f9a', dark:'#15557b', light:'#2c8db8', hi:'#8fe6ff' },
    pier:    { base:'#8a5f3c', dark:'#6d482b', light:'#a8784d', hi:'#c29463' },
    floor:   { base:'#6b4a39', dark:'#54382b', light:'#7f5a45', hi:'#936a51' },
    wall:    { base:'#33354f', dark:'#242639', light:'#434766', hi:'#565b80' },
    brick:   { base:'#744a4e', dark:'#5a383d', light:'#8c5d61', hi:'#a57175' },
    ancient: { base:'#5d5a66', dark:'#45434f', light:'#716d7c', hi:'#8b8599', rune:'#7ce8ff' }
  };

  /* ------------------------------------------------ ground tiles */
  function grassTile(ctx, x, y, seed, flowers) {
    const p = flowers ? PAL.flower : PAL.grass;
    const r = seeded(x, y, seed);
    PX.rect(ctx, x, y, T, T, p.base);
    // broad tone variation
    for (let i = 0; i < 3; i++) {
      const cx = x + 5 + r() * 22, cy = y + 5 + r() * 22;
      PX.ell(ctx, cx, cy, 5 + r() * 7, 3 + r() * 4, r() > .5 ? p.light : p.dark);
    }
    // dither + blade texture
    for (let i = 0; i < 22; i++) {
      const px = x + Math.floor(r() * T), py = y + Math.floor(r() * T);
      PX.rect(ctx, px, py, r() > .7 ? 2 : 1, 1, r() > .55 ? p.light : p.dark);
    }
    for (let i = 0; i < 3; i++) {
      const bx = x + 4 + Math.floor(r() * 25), by = y + 6 + Math.floor(r() * 24);
      PX.line(ctx, bx, by, bx - 1, by - 4, p.tuft, 1);
      PX.line(ctx, bx + 1, by, bx + 1, by - 5, p.hi, 1);
      PX.line(ctx, bx + 2, by, bx + 4, by - 3, p.dark, 1);
    }
    if (flowers) {
      const petals = p.petals;
      const count = 2 + Math.floor(r() * 3);
      for (let i = 0; i < count; i++) {
        const fx = x + 5 + Math.floor(r() * 22), fy = y + 6 + Math.floor(r() * 20);
        const col = petals[Math.floor(r() * petals.length)];
        PX.rect(ctx, fx, fy + 1, 1, 4, p.dark);
        PX.rect(ctx, fx - 1, fy - 1, 3, 3, col);
        PX.rect(ctx, fx - 2, fy, 1, 1, col); PX.rect(ctx, fx + 2, fy, 1, 1, col);
        PX.rect(ctx, fx, fy - 2, 1, 1, col); PX.rect(ctx, fx, fy + 2, 1, 1, col);
        PX.rect(ctx, fx, fy, 1, 1, '#fff4c2');
      }
    }
    // pebbles / clover
    if (r() > .62) {
      const sx = x + 6 + Math.floor(r() * 20), sy = y + 8 + Math.floor(r() * 18);
      PX.ell(ctx, sx, sy, 2, 1, p.dark); PX.rect(ctx, sx - 1, sy - 1, 2, 1, p.hi);
    }
  }

  function tallGrassTile(ctx, x, y, seed) {
    const p = PAL.grass;
    const r = seeded(x, y, seed + 99);
    PX.rect(ctx, x, y, T, T, '#123f2b');
    for (let i = 0; i < 4; i++) PX.ell(ctx, x + 5 + r() * 22, y + 5 + r() * 22, 4 + r() * 5, 3, '#174a31');
    for (let i = 0; i < 15; i++) {
      const bx = x + 2 + Math.floor(r() * 28), by = y + 10 + Math.floor(r() * 22);
      const h = 7 + Math.floor(r() * 9);
      PX.line(ctx, bx, by, bx - 2, by - h, '#1d5a38', 1);
      PX.line(ctx, bx + 1, by, bx + 1, by - h - 2, i % 3 ? '#48a86a' : '#2f8a52', 1);
      PX.line(ctx, bx + 3, by, bx + 5, by - h + 2, '#256c43', 1);
    }
    PX.rect(ctx, x, y + T - 1, T, 1, 'rgba(6,20,14,.35)');
  }

  function pathTile(ctx, x, y, seed, style) {
    const p = style === 'sand' ? PAL.sand : PAL.path;
    const r = seeded(x, y, seed);
    PX.rect(ctx, x, y, T, T, p.base);
    for (let i = 0; i < 4; i++) PX.ell(ctx, x + 4 + r() * 24, y + 4 + r() * 24, 4 + r() * 6, 3 + r() * 3, r() > .5 ? p.light : p.dark);
    for (let i = 0; i < 18; i++) PX.rect(ctx, x + Math.floor(r() * T), y + Math.floor(r() * T), 1, 1, r() > .5 ? p.light : p.dark);
    // scattered stones
    for (let i = 0; i < 3; i++) {
      if (r() > .4) {
        const sx = x + 5 + Math.floor(r() * 22), sy = y + 5 + Math.floor(r() * 22);
        PX.ell(ctx, sx, sy, 2, 1, p.pebble);
        PX.rect(ctx, sx - 1, sy - 1, 2, 1, p.hi);
      }
    }
    // faint wheel ruts
    if (style !== 'sand') {
      PX.rect(ctx, x, y + 10, T, 1, rgba('#7a512d', .16));
      PX.rect(ctx, x, y + 21, T, 1, rgba('#7a512d', .12));
    } else {
      PX.rect(ctx, x, y + 9, T, 1, rgba('#a9823f', .22));
      PX.rect(ctx, x, y + 20, T, 1, rgba('#fff0c2', .16));
    }
  }

  function sandTile(ctx, x, y, seed, pebbly) {
    const p = PAL.sand;
    const r = seeded(x, y, seed + 17);
    PX.rect(ctx, x, y, T, T, p.base);
    for (let i = 0; i < 3; i++) PX.ell(ctx, x + 4 + r() * 24, y + 4 + r() * 24, 5 + r() * 7, 2 + r() * 3, r() > .5 ? p.light : p.dark);
    // ripples
    for (let i = 0; i < 3; i++) {
      const wy = y + 6 + i * 9 + Math.floor(r() * 3);
      PX.rect(ctx, x + 3, wy, 10 + Math.floor(r() * 8), 1, rgba('#fff0c2', .22));
      PX.rect(ctx, x + 16, wy + 1, 9, 1, rgba('#a9823f', .18));
    }
    for (let i = 0; i < 10; i++) PX.rect(ctx, x + Math.floor(r() * T), y + Math.floor(r() * T), 1, 1, p.light);
    if (pebbly) {
      for (let i = 0; i < 4; i++) {
        const sx = x + 6 + Math.floor(r() * 20), sy = y + 6 + Math.floor(r() * 20);
        PX.ell(ctx, sx, sy, 2, 1, p.pebble); PX.rect(ctx, sx - 1, sy - 1, 2, 1, p.hi);
      }
    }
  }

  function rockTile(ctx, x, y, seed, mossy) {
    const p = PAL.rock;
    const r = seeded(x, y, seed + 5);
    PX.rect(ctx, x, y, T, T, p.base);
    for (let i = 0; i < 3; i++) PX.ell(ctx, x + 5 + r() * 22, y + 5 + r() * 22, 5 + r() * 6, 3 + r() * 3, r() > .5 ? p.light : p.dark);
    // cracks
    let cx = x + 4 + r() * 8, cy = y + 3 + r() * 8;
    for (let i = 0; i < 5; i++) { PX.rect(ctx, cx, cy, 1, 2, p.dark); cx += 2 + r() * 3; cy += 2 + r() * 2; }
    for (let i = 0; i < 12; i++) PX.rect(ctx, x + Math.floor(r() * T), y + Math.floor(r() * T), 1, 1, r() > .5 ? p.hi : p.dark);
    if (mossy) {
      for (let i = 0; i < 4; i++) PX.ell(ctx, x + 5 + r() * 22, y + 5 + r() * 22, 3 + r() * 4, 2, p.moss);
    }
  }

  function caveFloorTile(ctx, x, y, seed) {
    const p = PAL.cave;
    const r = seeded(x, y, seed + 31);
    PX.rect(ctx, x, y, T, T, p.base);
    for (let i = 0; i < 3; i++) PX.ell(ctx, x + 4 + r() * 24, y + 4 + r() * 24, 5 + r() * 6, 3 + r() * 3, r() > .5 ? p.light : p.dark);
    for (let i = 0; i < 14; i++) PX.rect(ctx, x + Math.floor(r() * T), y + Math.floor(r() * T), 1, 1, r() > .5 ? p.light : p.dark);
    if (r() > .55) {
      const bx = x + 6 + Math.floor(r() * 20), by = y + 6 + Math.floor(r() * 20);
      PX.rect(ctx, bx, by, 1, 3, rgba(p.glow, .5));
      PX.rect(ctx, bx - 1, by + 1, 3, 1, rgba(p.glow, .3));
    }
  }

  function cavePathTile(ctx, x, y, seed) {
    const p = PAL.caveP;
    const r = seeded(x, y, seed + 71);
    PX.rect(ctx, x, y, T, T, p.dark);
    PX.rect(ctx, x + 2, y + 2, T - 4, T - 4, p.base);
    PX.rect(ctx, x + 2, y + 2, T - 4, 2, p.light);
    PX.rect(ctx, x + 2, y + T - 4, T - 4, 2, p.dark);
    const split = 10 + Math.floor(r() * 12);
    PX.rect(ctx, x + split, y + 2, 1, T - 4, p.line);
    PX.rect(ctx, x + 2, y + 16, T - 4, 1, p.line);
    for (let i = 0; i < 6; i++) PX.rect(ctx, x + 3 + Math.floor(r() * 26), y + 3 + Math.floor(r() * 26), 1, 1, r() > .5 ? p.hi : p.dark);
  }

  function snowTile(ctx, x, y, seed, rocky) {
    const p = PAL.snow;
    const r = seeded(x, y, seed + 43);
    PX.rect(ctx, x, y, T, T, p.base);
    for (let i = 0; i < 3; i++) PX.ell(ctx, x + 4 + r() * 24, y + 5 + r() * 22, 6 + r() * 7, 3 + r() * 3, r() > .5 ? p.light : p.dark);
    for (let i = 0; i < 10; i++) PX.rect(ctx, x + Math.floor(r() * T), y + Math.floor(r() * T), 1, 1, r() > .5 ? p.hi : p.shadow);
    // drift shadow
    PX.rect(ctx, x, y + T - 2, T, 2, rgba(p.shadow, .35));
    if (rocky) {
      for (let i = 0; i < 3; i++) {
        const sx = x + 6 + Math.floor(r() * 20), sy = y + 7 + Math.floor(r() * 18);
        PX.ell(ctx, sx, sy, 3, 2, '#9fb6c6'); PX.rect(ctx, sx - 2, sy - 2, 4, 2, '#c8dce8');
      }
    }
  }

  function waterTile(ctx, x, y, seed) {
    const p = PAL.water;
    const r = seeded(x, y, seed + 88);
    PX.rect(ctx, x, y, T, T, p.base);
    for (let i = 0; i < 4; i++) PX.ell(ctx, x + 5 + r() * 22, y + 5 + r() * 22, 5 + r() * 7, 2 + r() * 2, r() > .5 ? p.light : p.dark);
    PX.rect(ctx, x + 4, y + 9 + Math.floor(r() * 3), 10, 1, rgba(p.hi, .28));
    PX.rect(ctx, x + 18, y + 22, 9, 1, rgba(p.hi, .22));
    PX.rect(ctx, x + 8, y + 26, 5, 1, rgba(p.dark, .5));
  }

  function pierTile(ctx, x, y, seed) {
    const p = PAL.pier;
    const r = seeded(x, y, seed + 12);
    PX.rect(ctx, x, y, T, T, p.dark);
    for (let i = 0; i < 4; i++) {
      PX.rect(ctx, x + i * 8, y + 1, 7, T - 2, i % 2 ? p.base : p.light);
      PX.rect(ctx, x + i * 8, y + 1, 7, 1, p.hi);
    }
    for (let i = 0; i < 5; i++) PX.rect(ctx, x + Math.floor(r() * 30), y + 4 + Math.floor(r() * 24), 2, 1, rgba('#4c3320', .25));
    PX.rect(ctx, x, y, T, 2, p.hi);
    PX.rect(ctx, x, y + T - 2, T, 2, p.dark);
  }

  function floorTile(ctx, x, y, seed) {
    const p = PAL.floor;
    const r = seeded(x, y, seed + 3);
    PX.rect(ctx, x, y, T, T, p.base);
    for (let i = 0; i < 2; i++) PX.rect(ctx, x, y + i * 16, T, 1, p.dark);
    PX.rect(ctx, x + 15, y, 1, T, rgba('#4a3025', .6));
    PX.rect(ctx, x + 4, y + 4, 10, 1, rgba(p.light, .5));
    PX.rect(ctx, x + 20, y + 20, 8, 1, rgba(p.light, .35));
    for (let i = 0; i < 5; i++) PX.rect(ctx, x + 3 + Math.floor(r() * 26), y + 3 + Math.floor(r() * 26), 1, 1, rgba('#3a241b', .3));
  }

  function wallTile(ctx, x, y, seed) {
    const p = PAL.wall;
    const r = seeded(x, y, seed + 8);
    PX.rect(ctx, x, y, T, T, p.base);
    PX.rect(ctx, x, y, T, 3, p.hi);
    PX.rect(ctx, x, y + T - 4, T, 4, p.dark);
    PX.rect(ctx, x + 4, y + 7, T - 8, 18, p.light);
    PX.rect(ctx, x + 5, y + 8, T - 10, 16, p.base);
    PX.rect(ctx, x + 4, y + 7, T - 8, 1, rgba('#8b90b8', .45));
    for (let i = 0; i < 3; i++) PX.rect(ctx, x + 7 + Math.floor(r() * 18), y + 11 + Math.floor(r() * 10), 1, 1, rgba('#1b1d30', .35));
  }

  function brickTile(ctx, x, y, seed) {
    const p = PAL.brick;
    const r = seeded(x, y, seed + 21);
    PX.rect(ctx, x, y, T, T, p.dark);
    for (let row = 0; row < 4; row++) {
      const off = row % 2 ? -8 : 0;
      for (let col = 0; col < 3; col++) {
        PX.rect(ctx, x + off + col * 16 + 1, y + row * 8 + 1, 14, 6, row % 2 ? p.base : p.light);
      }
    }
    for (let i = 0; i < 6; i++) PX.rect(ctx, x + Math.floor(r() * T), y + Math.floor(r() * T), 1, 1, rgba('#2f1c20', .3));
  }

  function ancientTile(ctx, x, y, seed) {
    const p = PAL.ancient;
    const r = seeded(x, y, seed + 55);
    PX.rect(ctx, x, y, T, T, p.dark);
    PX.rect(ctx, x + 1, y + 1, T - 2, T - 2, p.base);
    PX.rect(ctx, x + 1, y + 1, T - 2, 1, p.hi);
    PX.rect(ctx, x + 1, y + T - 2, T - 2, 1, p.dark);
    if (r() > .55) {
      const gx = x + 8 + Math.floor(r() * 14), gy = y + 8 + Math.floor(r() * 14);
      PX.rect(ctx, gx, gy, 1, 6, rgba(p.rune, .55));
      PX.rect(ctx, gx + 3, gy + 2, 1, 4, rgba(p.rune, .4));
      PX.rect(ctx, gx - 2, gy + 4, 7, 1, rgba(p.rune, .3));
    }
    for (let i = 0; i < 4; i++) PX.rect(ctx, x + 3 + Math.floor(r() * 26), y + 3 + Math.floor(r() * 26), 1, 1, rgba('#2e2c38', .4));
  }

  function doorstepTile(ctx, x, y, seed) {
    const r = seeded(x, y, seed + 6);
    PX.rect(ctx, x, y, T, T, '#a87a52');
    for (let i = 0; i < 4; i++) PX.rect(ctx, x + 2, y + 6 + i * 7, T - 4, 1, i % 2 ? '#936744' : '#bb8c5f');
    for (let i = 0; i < 6; i++) PX.rect(ctx, x + 3 + Math.floor(r() * 26), y + 3 + Math.floor(r() * 26), 1, 1, '#d3a878');
    PX.rect(ctx, x, y, T, 2, '#c99a6b');
  }

  function counterTile(ctx, x, y, seed) {
    PX.rect(ctx, x, y, T, T, '#4b3045');
    PX.rect(ctx, x, y, T, 12, '#8a5a68');
    PX.rect(ctx, x, y, T, 3, '#ab7484');
    PX.rect(ctx, x, y + 12, T, 2, '#2f1f2d');
    PX.rect(ctx, x + 6, y + 16, 20, 10, '#5c3b52');
    PX.rect(ctx, x + 7, y + 17, 18, 2, '#6d4862');
  }

  function roofTile(ctx, x, y, seed) {
    const p = PAL.brick;
    const r = seeded(x, y, seed + 41);
    PX.rect(ctx, x, y, T, T, '#4a2b32');
    for (let i = 0; i < 3; i++) {
      PX.rect(ctx, x, y + i * 11, T, 1, '#6b4149');
      PX.rect(ctx, x + ((i * 9) % 16), y + i * 11 + 2, 12, 8, i % 2 ? '#5c363f' : '#653c46');
    }
    for (let i = 0; i < 4; i++) PX.rect(ctx, x + Math.floor(r() * 30), y + Math.floor(r() * 30), 1, 1, rgba('#2c181d', .4));
  }

  function drawTile(ctx, tile, x, y, seed) {
    const tx = x * T, ty = y * T;
    switch (tile) {
      case 'grass': grassTile(ctx, tx, ty, seed); break;
      case 'grass_flower': grassTile(ctx, tx, ty, seed, true); break;
      case 'tall_grass': tallGrassTile(ctx, tx, ty, seed); break;
      case 'path': case 'path2': pathTile(ctx, tx, ty, seed); break;
      case 'sand': sandTile(ctx, tx, ty, seed); break;
      case 'sand_pebble': sandTile(ctx, tx, ty, seed, true); break;
      case 'sand_path': pathTile(ctx, tx, ty, seed, 'sand'); break;
      case 'rock': rockTile(ctx, tx, ty, seed); break;
      case 'snow': snowTile(ctx, tx, ty, seed); break;
      case 'snow_rock': snowTile(ctx, tx, ty, seed, true); break;
      case 'snow_path': snowTile(ctx, tx, ty, seed); pathTile(ctx, tx, ty, seed + 2, 'snow'); break;
      case 'cave_floor': caveFloorTile(ctx, tx, ty, seed); break;
      case 'cave_path': cavePathTile(ctx, tx, ty, seed); break;
      case 'water': waterTile(ctx, tx, ty, seed); break;
      case 'pier': pierTile(ctx, tx, ty, seed); break;
      case 'floor': floorTile(ctx, tx, ty, seed); break;
      case 'wall': wallTile(ctx, tx, ty, seed); break;
      case 'building_wall': brickTile(ctx, tx, ty, seed); break;
      case 'doorstep': doorstepTile(ctx, tx, ty, seed); break;
      case 'counter': counterTile(ctx, tx, ty, seed); break;
      case 'ancient_floor': ancientTile(ctx, tx, ty, seed); break;
      default:
        if (String(tile).endsWith('_roof')) roofTile(ctx, tx, ty, seed);
        else if (String(tile).includes('wall')) brickTile(ctx, tx, ty, seed);
        else grassTile(ctx, tx, ty, seed);
    }
  }

  /* ------------------------------------------------ transitions */
  function tileCat(tile) {
    if (!tile) return 'void';
    if (tile === 'water') return 'water';
    if (tile === 'pier') return 'pier';
    if (tile === 'path' || tile === 'path2' || tile === 'sand_path' || tile === 'snow_path' || tile === 'doorstep' || tile === 'cave_path') return 'path';
    if (tile === 'sand' || tile === 'sand_pebble') return 'sand';
    if (tile === 'snow' || tile === 'snow_rock') return 'snow';
    if (tile === 'rock') return 'rock';
    if (tile === 'cave_floor') return 'cave';
    if (tile === 'floor' || tile === 'counter') return 'floor';
    if (tile === 'wall' || tile.includes('wall') || tile.includes('roof')) return 'wall';
    if (tile === 'ancient_floor') return 'ancient';
    if (tile === 'tall_grass') return 'tall';
    return 'grass';
  }

  function fringeColors(tile) {
    const c = tileCat(tile);
    if (c === 'sand') return { tuft: '#c3a05d', hi: '#eed79b' };
    if (c === 'snow') return { tuft: '#c3d9e6', hi: '#ffffff' };
    if (c === 'rock') return { tuft: '#4b795a', hi: '#7f8da1' };
    if (c === 'cave') return { tuft: '#343b58', hi: '#454e70' };
    if (c === 'tall') return { tuft: '#1d5a38', hi: '#2f8a52' };
    if (c === 'ancient') return { tuft: '#45434f', hi: '#716d7c' };
    return { tuft: '#174a33', hi: '#469b6b' };
  }

  function transitions(ctx, map) {
    const { width, height, tiles } = map;
    const at = (x, y) => (x < 0 || y < 0 || x >= width || y >= height) ? null : tiles[y][x];
    for (let y = 0; y < height; y++) for (let x = 0; x < width; x++) {
      const tile = tiles[y][x], cat = tileCat(tile), tx = x * T, ty = y * T;
      const nbs = [[x, y - 1, 'n'], [x + 1, y, 'e'], [x, y + 1, 's'], [x - 1, y, 'w']];
      for (const [nx, ny, side] of nbs) {
        const n = at(nx, ny); if (n === null) continue;
        const ncat = tileCat(n);
        if (ncat === cat) continue;
        // Keep path-on-path variants seamless.
        if (cat === 'path' && ncat === 'path') continue;
        if (cat === 'water' && ncat !== 'water') {
          const foam = 'rgba(160,235,255,.5)';
          if (side === 'n') PX.rect(ctx, tx, ty, T, 2, foam);
          if (side === 's') PX.rect(ctx, tx, ty + T - 2, T, 2, foam);
          if (side === 'w') PX.rect(ctx, tx, ty, 2, T, foam);
          if (side === 'e') PX.rect(ctx, tx + T - 2, ty, 2, T, foam);
          continue;
        }
        if (cat === 'path' && (ncat === 'grass' || ncat === 'tall' || ncat === 'sand' || ncat === 'snow' || ncat === 'rock')) {
          const c = fringeColors(n);
          const r = seeded(x, y, ncat.length * 7);
          for (let i = 0; i < 4; i++) {
            const off = Math.floor(r() * 28);
            if (side === 'n') { PX.rect(ctx, tx + off, ty, 2, 2, c.tuft); PX.rect(ctx, tx + off + 1, ty + 2, 1, 2, c.hi); }
            if (side === 's') { PX.rect(ctx, tx + off, ty + T - 2, 2, 2, c.tuft); PX.rect(ctx, tx + off + 1, ty + T - 4, 1, 2, c.hi); }
            if (side === 'w') { PX.rect(ctx, tx, ty + off, 2, 2, c.tuft); PX.rect(ctx, tx + 2, ty + off + 1, 2, 1, c.hi); }
            if (side === 'e') { PX.rect(ctx, tx + T - 2, ty + off, 2, 2, c.tuft); PX.rect(ctx, tx + T - 4, ty + off + 1, 2, 1, c.hi); }
          }
        }
        if (cat === 'wall' && ncat !== 'wall') {
          if (side === 's') PX.rect(ctx, tx, ty + T - 3, T, 3, 'rgba(5,7,14,.45)');
        }
      }
    }
  }

  /* ------------------------------------------------ static layer */
  const layerCache = new Map();
  function buildStaticLayer(map) {
    if (!map) return null;
    const cached = layerCache.get(map.id);
    if (cached) return cached;
    const c = document.createElement('canvas');
    c.width = map.width * T; c.height = map.height * T;
    const ctx = c.getContext('2d');
    ctx.imageSmoothingEnabled = false;
    const seed = (hashStr(map.id) % 99991) | 0;
    for (let y = 0; y < map.height; y++) for (let x = 0; x < map.width; x++) {
      drawTile(ctx, map.tiles[y][x], x, y, seed + x * 131 + y * 977);
    }
    transitions(ctx, map);
    // bake soft ambient occlusion at map borders
    const edge = ctx.createLinearGradient(0, 0, 0, 64);
    edge.addColorStop(0, 'rgba(4,6,16,.35)'); edge.addColorStop(1, 'rgba(4,6,16,0)');
    ctx.fillStyle = edge; ctx.fillRect(0, 0, c.width, 64);
    // props sorted so taller / lower objects paint last
    const props = map.objects.slice().sort((a, b) => (a.y + (a.height || 1)) - (b.y + (b.height || 1)));
    for (const o of props) Art.drawProp(ctx, o, map);
    layerCache.set(map.id, c);
    return c;
  }

  Art.T = T;
  Art.PAL = PAL;
  Art.hashStr = hashStr;
  Art.seeded = seeded;
  Art.rgba = rgba;
  Art.lerp = lerp;
  Art.centerText = centerText;
  Art.drawTile = drawTile;
  Art.tileCat = tileCat;
  Art.buildStaticLayer = buildStaticLayer;
  Art._seeded = seeded;
})();

/* ============================================================
   POKÉMON ECLIPSE — art engine (props)
   Trees, buildings, shrines, crystals, market stalls and more.
   ============================================================ */
'use strict';

(function () {
  const T = 32;
  const rgba = Art.rgba;
  const seeded = Art.seeded;

  function shadow(ctx, cx, cy, rx, ry, a = .3) {
    ctx.save();
    ctx.fillStyle = `rgba(4,8,16,${a})`;
    ctx.beginPath(); ctx.ellipse(cx, cy, rx, ry, 0, 0, Math.PI * 2); ctx.fill();
    ctx.restore();
  }

  const BUILDING = {
    house:       { roof:'#b4534f', roofD:'#7f363a', roofL:'#d97a70', wall:'#e9d9bd', wallD:'#c7b08c', trim:'#7d5135', accent:'#f5c542' },
    lab:         { roof:'#337a8a', roofD:'#1d505e', roofL:'#5fb8c4', wall:'#e6eef0', wallD:'#c0d2d6', trim:'#4a6a74', accent:'#7ce8ff' },
    shop:        { roof:'#b9793a', roofD:'#855322', roofL:'#e0a35a', wall:'#efdcb8', wallD:'#ccb488', trim:'#7a4a2a', accent:'#ffd166' },
    pokecenter:  { roof:'#ad4a5c', roofD:'#7a2e3c', roofL:'#d97a88', wall:'#f3e7e6', wallD:'#d0bcbc', trim:'#8a5a62', accent:'#ff5a6e' },
    gym:         { roof:'#4a7a4a', roofD:'#2c4e2e', roofL:'#74ad6a', wall:'#ddd6ba', wallD:'#b8b090', trim:'#5a4a2e', accent:'#8ee05a' },
    league_hall: { roof:'#4f5f9a', roofD:'#354067', roofL:'#8090c8', wall:'#dfe5f2', wallD:'#b4bdd4', trim:'#45506e', accent:'#f5c542' }
  };

  function drawBuilding(ctx, o) {
    const left = (o.x - 1) * T, top = (o.y - 1) * T, W = 4 * T, H = 3 * T;
    const p = BUILDING[o.type] || BUILDING.house;
    shadow(ctx, left + W / 2, top + H - 4, W * .47, 8, .32);

    // walls
    PX.rect(ctx, left + 4, top + 32, W - 8, H - 34, p.wallD);
    PX.rect(ctx, left + 6, top + 34, W - 12, H - 38, p.wall);
    PX.rect(ctx, left + 6, top + H - 16, W - 12, 12, p.wallD);
    PX.rect(ctx, left + 6, top + H - 18, W - 12, 2, p.trim);
    // siding
    for (let i = 0; i < 6; i++) PX.rect(ctx, left + 8, top + 38 + i * 8, W - 16, 1, rgba(p.wallD, .45));
    // corner trim
    PX.rect(ctx, left + 5, top + 30, 5, H - 32, p.trim);
    PX.rect(ctx, left + W - 10, top + 30, 5, H - 32, p.trim);

    // roof
    PX.tri(ctx, left - 8, top + 40, left + W / 2, top - 6, left + W + 8, top + 40, p.roofD);
    PX.tri(ctx, left + 2, top + 39, left + W / 2, top + 1, left + W - 2, top + 39, p.roof);
    PX.tri(ctx, left + 14, top + 36, left + W / 2 - 10, top + 8, left + W / 2 + 2, top + 12, p.roofL);
    PX.rect(ctx, left - 8, top + 39, W + 16, 4, p.roofD);
    PX.rect(ctx, left - 8, top + 39, W + 16, 1, p.roofL);
    // shingles
    for (let i = 0; i < 4; i++) {
      const yy = top + 16 + i * 6;
      PX.rect(ctx, left + 20 + i * 3, yy, W - 40 - i * 6, 1, rgba(p.roofD, .45));
    }
    // ridge cap
    PX.rect(ctx, left + W / 2 - 2, top + 2, 4, 10, p.roofD);
    PX.rect(ctx, left + W / 2 - 1, top + 2, 2, 7, p.roofL);

    // windows
    const winY = top + 50;
    for (const wx of [left + 18, left + W - 40]) {
      PX.rect(ctx, wx, winY, 22, 18, p.trim);
      PX.rect(ctx, wx + 2, winY + 2, 18, 14, '#87d8ef');
      PX.rect(ctx, wx + 2, winY + 2, 18, 5, '#bdf0ff');
      PX.rect(ctx, wx + 10, winY + 2, 2, 14, p.trim);
      PX.rect(ctx, wx + 2, winY + 8, 18, 1, p.trim);
      PX.rect(ctx, wx + 3, winY + 3, 4, 2, '#ffffff');
      // sill
      PX.rect(ctx, wx - 2, winY + 18, 26, 3, p.wallD);
    }

    // door
    const dx = left + 2 * T - 11, dy = top + H - 34;
    PX.rect(ctx, dx - 2, dy - 2, 26, 36, p.trim);
    PX.rect(ctx, dx, dy, 22, 32, '#5a3826');
    PX.rect(ctx, dx + 2, dy + 2, 18, 28, '#7a4f33');
    PX.rect(ctx, dx + 2, dy + 2, 18, 2, '#96694a');
    PX.rect(ctx, dx + 15, dy + 16, 2, 2, p.accent);
    PX.rect(ctx, dx - 4, dy + 32, 30, 3, p.wallD);
    PX.rect(ctx, dx + 4, dy + 6, 14, 8, rgba('#2a1a14', .5));

    // type-specific signage
    if (o.type === 'pokecenter') {
      PX.ell(ctx, left + 2 * T, top + 50, 9, 9, '#f5f5f5');
      PX.rect(ctx, left + 2 * T - 2, top + 39, 4, 22, '#e8445a');
      PX.rect(ctx, left + 2 * T - 9, top + 46, 18, 4, '#e8445a');
      PX.rect(ctx, left + 2 * T - 1, top + 41, 2, 18, '#ff8090');
    }
    if (o.type === 'lab') {
      // satellite dish
      PX.ell(ctx, left + 28, top + 10, 11, 6, '#cdd8de');
      PX.ell(ctx, left + 28, top + 9, 8, 4, '#eef8fb');
      PX.line(ctx, left + 28, top + 14, left + 28, top + 28, '#8a9aa4', 2);
      PX.rect(ctx, left + 25, top + 27, 7, 3, '#6c7c86');
      // round window
      PX.ell(ctx, left + 2 * T, top + 53, 10, 10, p.trim);
      PX.ell(ctx, left + 2 * T, top + 53, 7, 7, '#7ce8ff');
      PX.ell(ctx, left + 2 * T - 2, top + 51, 3, 2, '#e6ffff');
    }
    if (o.type === 'shop') {
      // awning
      for (let i = 0; i < 8; i++) PX.rect(ctx, left + 10 + i * 14, top + 44, 14, 9, i % 2 ? '#fff2d0' : '#d9694f');
      PX.rect(ctx, left + 10, top + 52, W - 20, 4, '#8a3a2a');
      PX.rect(ctx, left + 10, top + 52, W - 20, 1, '#ffe2a8');
      // crates
      PX.rect(ctx, left + 10, top + H - 22, 14, 14, '#9a6538');
      PX.rect(ctx, left + 11, top + H - 21, 12, 3, '#c28a52');
      PX.rect(ctx, left + 10, top + H - 14, 14, 2, '#734a28');
    }
    if (o.type === 'gym') {
      PX.ell(ctx, left + 2 * T, top + 48, 13, 11, '#2f4a30');
      PX.ell(ctx, left + 2 * T, top + 48, 10, 8, p.accent);
      PX.tri(ctx, left + 2 * T, top + 41, left + 2 * T - 7, top + 53, left + 2 * T + 7, top + 53, '#2f4a30');
      PX.rect(ctx, left + 2 * T - 1, top + 45, 2, 6, '#2f4a30');
      // banners
      PX.rect(ctx, left + 9, top + 56, 5, 22, '#c9c08a');
      PX.rect(ctx, left + W - 14, top + 56, 5, 22, '#c9c08a');
    }
    if (o.type === 'league_hall') {
      // columns
      for (const cx of [left + 14, left + W - 18]) {
        PX.rect(ctx, cx, top + 44, 6, 42, p.wallD);
        PX.rect(ctx, cx + 1, top + 44, 2, 42, '#f0f4fc');
        PX.rect(ctx, cx - 2, top + 42, 10, 3, p.accent);
      }
      PX.ell(ctx, left + 2 * T, top + 47, 11, 10, p.accent);
      PX.ell(ctx, left + 2 * T, top + 47, 7, 6, '#fff4c8');
      PX.rect(ctx, left + 2 * T - 1, top + 41, 2, 12, p.trim);
    }
    if (o.type === 'house') {
      // chimney + flower boxes
      PX.rect(ctx, left + W - 34, top + 6, 10, 22, '#7a4a3a');
      PX.rect(ctx, left + W - 36, top + 4, 14, 4, '#5a3428');
      for (const wx of [left + 18, left + W - 40]) {
        PX.rect(ctx, wx - 2, top + 68, 26, 4, '#7a4a2a');
        PX.rect(ctx, wx, top + 65, 4, 3, '#3d7a3a');
        PX.rect(ctx, wx + 8, top + 64, 3, 4, '#f5a0c0');
        PX.rect(ctx, wx + 17, top + 65, 4, 3, '#3d7a3a');
      }
    }
    // doorstep glow
    PX.rect(ctx, left + 2 * T - 14, top + H - 3, 28, 2, rgba(p.accent, .35));
  }

  function drawTree(ctx, o) {
    const cx = o.x * T + 16, by = o.y * T + 31;
    const big = o.type === 'old_tree';
    const scale = big ? 1.5 : 1;
    shadow(ctx, cx, by - 1, 15 * scale, 5 * scale, .3);
    // trunk
    PX.rect(ctx, cx - 4, by - 16, 8, 16, '#4a2e20');
    PX.rect(ctx, cx - 3, by - 16, 5, 14, '#6a442c');
    PX.rect(ctx, cx - 2, by - 15, 2, 9, '#8a5e3c');
    PX.rect(ctx, cx - 6, by - 2, 12, 3, '#3a2418');
    if (big) {
      PX.line(ctx, cx - 3, by - 12, cx - 12, by - 24, '#4a2e20', 4);
      PX.line(ctx, cx + 3, by - 13, cx + 12, by - 26, '#4a2e20', 4);
    }
    // canopy clusters
    const clusters = big
      ? [[0, -36, 20, 15], [-16, -26, 14, 12], [16, -27, 15, 12], [-8, -44, 13, 10], [10, -44, 12, 10], [0, -22, 17, 11]]
      : [[0, -27, 15, 13], [-9, -20, 11, 9], [9, -20, 11, 9], [0, -34, 11, 8]];
    for (const [dx, dy, rx, ry] of clusters) PX.ell(ctx, cx + dx, by + dy, rx + 2, ry + 2, '#0f3024');
    for (const [dx, dy, rx, ry] of clusters) PX.ell(ctx, cx + dx, by + dy, rx, ry, '#185039');
    // light tops
    for (const [dx, dy, rx, ry] of clusters) {
      PX.ell(ctx, cx + dx - 2, by + dy - 3, rx * .62, ry * .5, '#256b48');
      PX.ell(ctx, cx + dx - 4, by + dy - 5, rx * .34, ry * .26, '#3a8a59');
    }
    // leaf speckles
    for (let i = 0; i < 12; i++) {
      const r = seeded(o.x * 13 + i, o.y * 7, i * 91);
      const px = cx - 18 + r() * 36, py = by - (big ? 46 : 34) + r() * (big ? 34 : 26);
      PX.rect(ctx, px, py, 1, 1, i % 3 ? '#3f9a63' : '#7ac08a');
    }
  }

  function drawSign(ctx, o) {
    const x = o.x * T, y = o.y * T;
    shadow(ctx, x + 16, y + 30, 10, 3, .28);
    PX.rect(ctx, x + 14, y + 17, 5, 14, '#5a3a24');
    PX.rect(ctx, x + 15, y + 17, 2, 12, '#7a5234');
    PX.rect(ctx, x + 3, y + 7, 26, 15, '#5a3a24');
    PX.rect(ctx, x + 4, y + 8, 24, 13, '#c69a5c');
    PX.rect(ctx, x + 4, y + 8, 24, 3, '#e2bd82');
    PX.rect(ctx, x + 7, y + 13, 9, 1, '#7a5234');
    PX.rect(ctx, x + 7, y + 16, 14, 1, '#7a5234');
    PX.rect(ctx, x + 20, y + 12, 6, 4, '#8a5a34');
    PX.rect(ctx, x + 22, y + 13, 2, 2, '#e2bd82');
  }

  function drawFountain(ctx, o) {
    const cx = o.x * T + 16, cy = o.y * T + 18;
    shadow(ctx, cx, o.y * T + 29, 15, 5, .3);
    PX.ell(ctx, cx, cy + 5, 16, 8, '#3a4d60');
    PX.ell(ctx, cx, cy + 4, 14, 6, '#9bb7c8');
    PX.ell(ctx, cx, cy + 3, 11, 4, '#2c7fa0');
    PX.ell(ctx, cx - 2, cy + 2, 7, 2, '#4db6d6');
    PX.rect(ctx, cx - 2, cy - 13, 4, 15, '#b8ccd8');
    PX.rect(ctx, cx - 1, cy - 13, 2, 12, '#e0f0f8');
    PX.ell(ctx, cx, cy - 13, 6, 3, '#d8ecf4');
    PX.ell(ctx, cx, cy - 13, 4, 2, '#8fe6ff');
    PX.rect(ctx, cx - 1, cy - 24, 2, 9, 'rgba(160,235,255,.65)');
    PX.rect(ctx, cx - 5, cy - 20, 2, 2, 'rgba(160,235,255,.5)');
    PX.rect(ctx, cx + 4, cy - 19, 2, 2, 'rgba(160,235,255,.5)');
    // rim sparkle
    PX.rect(ctx, cx - 12, cy + 5, 4, 1, '#e8fbff');
    PX.rect(ctx, cx + 8, cy + 6, 3, 1, '#c8f4ff');
  }

  function drawCrystal(ctx, o) {
    const cx = o.x * T + 16, by = o.y * T + 26;
    shadow(ctx, cx, by + 3, 12, 4, .3);
    const shards = [[0, -18, 8, 18], [-10, -9, 6, 11], [10, -11, 6, 13]];
    for (const [dx, h, w, len] of shards) {
      PX.tri(ctx, cx + dx, by - len - 4, cx + dx - w, by, cx + dx + w, by, '#2f2350');
      PX.tri(ctx, cx + dx, by - len - 2, cx + dx - w + 1, by - 1, cx + dx + w - 1, by - 1, '#7a5cc8');
      PX.tri(ctx, cx + dx, by - len - 2, cx + dx - 2, by - 1, cx + dx + 1, by - 1, '#c9b4ff');
      PX.rect(ctx, cx + dx - 1, by - len, 2, len - 2, rgba('#8de0ff', .55));
    }
    // glow base
    PX.ell(ctx, cx, by - 1, 14, 4, rgba('#9b7bff', .35));
    PX.rect(ctx, cx - 2, by - 8, 2, 2, '#f4ecff');
  }

  function drawLantern(ctx, o) {
    const cx = o.x * T + 16, by = o.y * T + 30;
    shadow(ctx, cx, by, 7, 2, .3);
    PX.rect(ctx, cx - 2, by - 18, 4, 18, '#3a2830');
    PX.rect(ctx, cx - 1, by - 18, 1, 16, '#5a3e44');
    PX.rect(ctx, cx - 6, by - 4, 12, 3, '#2a1c24');
    PX.rect(ctx, cx - 6, by - 27, 12, 10, '#2a1c24');
    PX.rect(ctx, cx - 5, by - 26, 10, 8, '#ffcf6e');
    PX.rect(ctx, cx - 4, by - 25, 3, 5, '#fff0b0');
    PX.rect(ctx, cx - 6, by - 29, 12, 3, '#3a2830');
    PX.rect(ctx, cx - 1, by - 31, 2, 2, '#5a3e44');
    PX.rect(ctx, cx - 5, by - 17, 10, 2, '#3a2830');
    PX.ell(ctx, cx, by - 22, 12, 9, rgba('#ffb84d', .16));
  }

  function drawGlowMushroom(ctx, o) {
    const cx = o.x * T + 16, by = o.y * T + 28;
    shadow(ctx, cx, by + 2, 9, 3, .25);
    for (let i = 0; i < 3; i++) {
      const dx = (i - 1) * 8, h = 7 + i * 3;
      PX.rect(ctx, cx + dx - 1, by - h, 3, h, '#c8d8e8');
      PX.ell(ctx, cx + dx, by - h - 2, 6 - i, 4, '#2f4a7a');
      PX.ell(ctx, cx + dx - 1, by - h - 3, 4 - i, 2, '#7ce8ff');
      PX.rect(ctx, cx + dx - 2, by - h - 4, 2, 1, '#d8feff');
    }
    PX.ell(ctx, cx, by - 6, 15, 6, rgba('#7ce8ff', .10));
  }

  function drawHealingStation(ctx, o) {
    const x = o.x * T, y = o.y * T;
    shadow(ctx, x + 16, y + 29, 13, 4, .3);
    PX.rect(ctx, x + 5, y + 10, 22, 19, '#3a2036');
    PX.rect(ctx, x + 6, y + 11, 20, 17, '#e8e4f0');
    PX.rect(ctx, x + 6, y + 11, 20, 4, '#ffffff');
    PX.rect(ctx, x + 8, y + 16, 16, 10, '#5a3a56');
    PX.ell(ctx, x + 16, y + 20, 6, 5, '#ff9eb0');
    PX.rect(ctx, x + 15, y + 17, 2, 7, '#fff0f4');
    PX.rect(ctx, x + 12, y + 19, 8, 2, '#fff0f4');
    PX.rect(ctx, x + 7, y + 27, 18, 3, '#c8c2d8');
    PX.ell(ctx, x + 16, y + 16, 11, 6, rgba('#ff8aa0', .18));
  }

  function drawAltar(ctx, o) {
    const cx = o.x * T + 16, by = o.y * T + 30, kind = o.type;
    const colors = kind === 'soul_altar' ? ['#2a2440', '#6b5aa0', '#f5c542', '#fff1b0']
      : kind === 'relic_altar' ? ['#1f2a3c', '#4f6a8a', '#7ce8ff', '#e6ffff']
      : ['#2a2440', '#5a5080', '#c9a0ff', '#f4ecff'];
    shadow(ctx, cx, by, 15, 5, .32);
    PX.rect(ctx, cx - 16, by - 7, 32, 8, colors[0]);
    PX.rect(ctx, cx - 14, by - 10, 28, 5, colors[1]);
    PX.rect(ctx, cx - 14, by - 10, 28, 1, colors[3]);
    PX.rect(ctx, cx - 5, by - 24, 10, 15, colors[1]);
    PX.rect(ctx, cx - 4, by - 24, 3, 14, colors[3]);
    PX.ell(ctx, cx, by - 27, 7, 5, colors[2]);
    PX.ell(ctx, cx - 1, by - 28, 4, 2, colors[3]);
    PX.ell(ctx, cx, by - 27, 13, 8, rgba(colors[2], .18));
    PX.rect(ctx, cx - 13, by - 14, 2, 2, rgba(colors[2], .7));
    PX.rect(ctx, cx + 11, by - 14, 2, 2, rgba(colors[2], .7));
  }

  function drawArch(ctx, o) {
    const x = o.x * T, y = o.y * T;
    const wide = (o.width || 1) * T, tall = 64;
    const cx = x + wide / 2;
    shadow(ctx, cx, y + 30, wide * .5, 6, .3);
    if (o.type === 'obsidian_gate') {
      PX.rect(ctx, x + 4, y - 28, 8, 58, '#181428');
      PX.rect(ctx, x + wide - 12, y - 28, 8, 58, '#181428');
      PX.rect(ctx, x + 2, y - 34, wide - 4, 10, '#241c40');
      PX.rect(ctx, x + 6, y - 32, wide - 12, 3, '#4a3a78');
      PX.ell(ctx, cx, y - 14, 10, 8, '#9b7bff');
      PX.ell(ctx, cx, y - 14, 6, 5, '#e0d4ff');
      PX.rect(ctx, x + 8, y - 22, 3, 3, '#c9b4ff');
      PX.rect(ctx, x + wide - 11, y - 22, 3, 3, '#c9b4ff');
    } else if (o.type === 'victory_arch') {
      PX.rect(ctx, x + 2, y - 36, 9, 66, '#c8ccd8');
      PX.rect(ctx, x + wide - 11, y - 36, 9, 66, '#c8ccd8');
      PX.rect(ctx, x + 3, y - 36, 3, 64, '#eef2f8');
      PX.rect(ctx, x + wide - 10, y - 36, 3, 64, '#eef2f8');
      PX.rect(ctx, x, y - 42, wide, 8, '#f5c542');
      PX.rect(ctx, x + 4, y - 41, wide - 8, 2, '#fff2b8');
      PX.rect(ctx, x + 2, y - 30, wide - 4, 4, '#f5c542');
      PX.ell(ctx, cx, y - 34, 7, 7, '#fff2b8');
      PX.rect(ctx, cx - 1, y - 40, 2, 12, '#8a6a10');
    } else {
      PX.rect(ctx, x + 3, y - 30, 8, 60, '#5a5864');
      PX.rect(ctx, x + wide - 11, y - 30, 8, 60, '#5a5864');
      PX.rect(ctx, x, y - 36, wide, 8, '#706c7c');
      PX.rect(ctx, x + 3, y - 35, wide - 6, 2, '#8b8599');
      PX.rect(ctx, cx - 2, y - 26, 4, 4, '#7ce8ff');
      PX.rect(ctx, x + 5, y - 20, 2, 12, rgba('#7ce8ff', .5));
      PX.rect(ctx, x + wide - 7, y - 20, 2, 12, rgba('#7ce8ff', .5));
    }
    PX.rect(ctx, x + 5, y + 24, wide - 10, 4, 'rgba(4,6,16,.3)');
  }

  function drawShrine(ctx, o) {
    const cx = o.x * T + 16, by = o.y * T + 30;
    shadow(ctx, cx, by, 17, 5, .3);
    PX.rect(ctx, cx - 17, by - 5, 34, 6, '#3a2f3a');
    PX.rect(ctx, cx - 14, by - 7, 28, 3, '#5a4a58');
    // torii-like shrine
    PX.rect(ctx, cx - 15, by - 30, 5, 23, '#7a3a3a');
    PX.rect(ctx, cx + 10, by - 30, 5, 23, '#7a3a3a');
    PX.rect(ctx, cx - 18, by - 34, 36, 5, '#8a4444');
    PX.rect(ctx, cx - 18, by - 34, 36, 1, '#c06a60');
    PX.rect(ctx, cx - 13, by - 27, 26, 3, '#6a3038');
    PX.rect(ctx, cx - 8, by - 23, 16, 12, '#4a2f3a');
    PX.ell(ctx, cx, by - 18, 5, 4, '#7ce8ff');
