      grad.addColorStop(1, 'rgba(70,40,160,0)');
      ctx.fillStyle = grad;
      ctx.beginPath(); ctx.moveTo(0, 80 + i * 30);
      for (let x = 0; x <= w; x += 26) ctx.lineTo(x, 80 + i * 30 + Math.sin(x * .007 + time * .35 + i * 1.6) * 30);
