195:/* ---------- overlay ---------- */
196:#overlay {
202:#overlay > * { pointer-events: auto; }
203:#overlay.hidden { display: none; }
484:.menu-window {
498:.menu-title {
513:.menu-list { display: grid; gap: 8px; }
514:.menu-option {
527:.menu-option:hover, .menu-option.selected, .menu-option:focus-visible {
533:.menu-option.selected { transform: translateY(-1px); }
534:.menu-option:disabled { opacity: .5; cursor: not-allowed; }
543:.menu-starters { width: min(900px, calc(100% - 32px)); padding: 24px 26px 18px; }
544:.menu-starters .menu-title { font-size: 13px; margin-bottom: 12px; }
545:.menu-starters .menu-description { font-size: 25px; }
546:.menu-starters .menu-list { grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 12px; }
622:  .menu-window { width: calc(100% - 24px); padding: 18px 16px 14px; }
623:  .menu-starters { width: calc(100% - 20px); padding: 16px 12px 12px; }
624:  .menu-starters .menu-list { gap: 8px; }
630:  .menu-starters .menu-title { font-size: 10px; }
631:  .menu-starters .menu-description { font-size: 20px; margin-bottom: 10px; }
632:  .menu-starters .menu-list { gap: 6px; }
637:  .menu-starters .menu-footer { margin-top: 9px; font-size: 15px; }
  border-color: #fff0b8;
  text-shadow: 0 1px 0 rgba(255,255,255,.5);
  box-shadow: 0 4px 0 #6b3e0a, inset 0 1px 0 rgba(255,255,255,.5);
}
.pbtn.gold:active { box-shadow: 0 1px 0 #6b3e0a; }
.pbtn.small { font-size: 8px; padding: 9px 12px 8px; }
.pbtn.danger { border-color: #b45a6a; background: linear-gradient(180deg,#4a2230,#2a1018); }
.pbtn:disabled { filter: grayscale(.7) brightness(.7); cursor: not-allowed; transform: none; }

/* ---------- generic panel ---------- */
.screen {
  position: absolute;
  inset: 0;
  background:
    radial-gradient(800px 500px at 50% 0%, rgba(64,84,160,.28), transparent 65%),
    linear-gradient(180deg, rgba(8,11,24,.96), rgba(5,7,14,.985));
  display: flex;
  flex-direction: column;
  padding: 26px 30px 20px;
  z-index: 21;
}
.screen-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 16px;
  border-bottom: 2px solid #2a3560;
  padding-bottom: 12px;
}
.screen-title {
  font-family: 'PixelTitle', monospace;
  font-size: 20px;
  color: var(--gold);
  text-shadow: 0 3px 0 #000;
  letter-spacing: 1px;
}
.screen-sub { color: var(--muted); font-size: 23px; line-height: 1; margin-top: 8px; }
.screen-body { flex: 1; overflow: auto; min-height: 0; }
.screen-foot { display: flex; gap: 10px; justify-content: flex-end; padding-top: 14px; }
.xbtn {
  font-family: 'PixelTitle', monospace;
  font-size: 9px;
  color: #d8def5;
  background: #1a2244;
  border: 2px solid #3c4a7d;
  border-radius: 8px;
  padding: 10px 12px;
  cursor: pointer;
}
.xbtn:hover { background: #253061; }

/* ---------- battle UI ---------- */
.battle-ui {
  position: absolute;
  left: 14px; right: 14px; bottom: 12px;
  height: 126px;
  z-index: 10;
  display: flex;
  gap: 10px;
}
.battle-text {
  flex: 1;
  background: linear-gradient(180deg, rgba(30,39,74,.98), rgba(12,16,32,.99));
  border: 3px solid #e8d9a0;
  border-radius: 12px;
  box-shadow: 0 0 0 3px #141a33, 0 8px 0 rgba(0,0,0,.55), inset 0 0 0 2px #2e3a68;
  padding: 12px 18px;
  display: flex;
  align-items: center;
  font-size: 27px;
  line-height: 1.1;
  color: #f7f4e9;
  text-shadow: 0 2px 0 #000;
}
.battle-cmd {
  width: 330px;
  display: grid;
  grid-template-columns: 1fr 1fr;
  grid-template-rows: 1fr 1fr;
  gap: 7px;
}
.battle-cmd .pbtn { font-size: 9px; padding: 0 8px; display: flex; align-items: center; justify-content: center; }
.battle-cmd .pbtn .key { color: #8fa1d8; font-size: 8px; margin-left: 6px; }

.moves {
  position: absolute;
  left: 14px; right: 14px; bottom: 12px;
  height: 126px;
  z-index: 10;
  display: flex;
  gap: 10px;
}
.move-grid { flex: 1; display: grid; grid-template-columns: 1fr 1fr; grid-template-rows: 1fr 1fr; gap: 7px; }
.move-btn {
  text-align: left;
  justify-content: flex-start;
  padding: 0 14px;
  display: flex;
  flex-direction: column;
  gap: 4px;
}
.move-btn .mname { font-size: 9px; }
.move-btn .mmeta { font-family: 'PixelBody'; font-size: 19px; color: #b9c4e8; letter-spacing: .5px; line-height: 1; }
.move-btn .mtype {
  font-family: 'PixelTitle'; font-size: 7px; padding: 3px 6px 2px; border-radius: 5px; color: #080a14;
  background: #cbd5e1; display: inline-block;
}
.move-btn .row { display: flex; align-items: center; gap: 8px; }

/* ---------- lists / cards ---------- */
.party-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 12px; }
.party-card {
  display: flex;
  gap: 12px;
  background: linear-gradient(180deg, #182044, #10162e);
  border: 2px solid #35437a;
  border-radius: 12px;
  padding: 10px 12px;
  cursor: pointer;
  position: relative;
  transition: border-color .12s, transform .12s;
}
.party-card:hover { border-color: #6f86d6; transform: translateY(-1px); }
.party-card.active { border-color: var(--gold); box-shadow: 0 0 0 2px rgba(245,197,66,.25); }
.party-card.fainted { opacity: .55; }
.pc-sprite { width: 74px; height: 74px; flex: 0 0 74px; image-rendering: pixelated; align-self: center; }
.pc-info { flex: 1; min-width: 0; }
.pc-top { display: flex; justify-content: space-between; align-items: baseline; gap: 6px; }
.pc-name { font-family: 'PixelTitle'; font-size: 9px; color: #fff; text-shadow: 0 2px 0 #000; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.pc-lv { font-family: 'PixelTitle'; font-size: 8px; color: var(--gold); }
.pc-types { display: flex; gap: 5px; margin: 6px 0 5px; }
.tchip { font-family: 'PixelTitle'; font-size: 6px; padding: 3px 5px 2px; border-radius: 4px; color: #05060c; letter-spacing: .3px; }
.pc-hp { font-family: 'PixelBody'; font-size: 17px; color: #cdd6f4; display: flex; justify-content: space-between; }
.bar { height: 7px; background: #05070f; border-radius: 4px; overflow: hidden; border: 1px solid #2b3560; }
.bar > i { display: block; height: 100%; background: linear-gradient(90deg, #3ddc84, #6ee7b7); border-radius: 4px; transition: width .4s; }
.bar.mid > i { background: linear-gradient(90deg, #f5c542, #fbbf24); }
.bar.low > i { background: linear-gradient(90deg, #ef4444, #f87171); }
.pc-xp { margin-top: 5px; }
.pc-xp .bar { height: 4px; }
.pc-xp .bar > i { background: linear-gradient(90deg, #67e8f9, #9b7bff); }
.pc-tag { position: absolute; right: 8px; bottom: 8px; font-family: 'PixelTitle'; font-size: 6px; color: #93a4d8; }
.pc-soul { position: absolute; left: -2px; top: -2px; background: var(--violet); color: #fff; font-family: 'PixelTitle'; font-size: 6px; padding: 3px 5px; border-radius: 5px; box-shadow: 0 0 12px rgba(155,123,255,.8); }

.tabbar { display: flex; gap: 8px; margin-bottom: 16px; flex-wrap: wrap; }
.tab {
  font-family: 'PixelTitle'; font-size: 8px; color: #aab6dd; background: #111731;
  border: 2px solid #2b3762; border-radius: 8px; padding: 10px 14px; cursor: pointer;
}
.tab.on { color: #1b1403; background: linear-gradient(180deg,#ffe9a0,#f5c542); border-color: #fff0b8; }
.item-list { display: flex; flex-direction: column; gap: 8px; }
.item-row {
  display: flex; align-items: center; gap: 12px; background: linear-gradient(180deg,#161e3d,#0f142b);
  border: 2px solid #2c3868; border-radius: 10px; padding: 11px 14px; cursor: pointer;
}
.item-row:hover { border-color: #6f86d6; }
.item-ico { width: 34px; height: 34px; border-radius: 8px; background: #2b3762; display: grid; place-items: center; font-size: 22px; }
.item-name { flex: 1; font-family: 'PixelTitle'; font-size: 9px; }
.item-desc { font-size: 20px; color: #aeb9dd; line-height: 1; margin-top: 4px; font-family: 'PixelBody'; }
.item-qty { font-family: 'PixelTitle'; font-size: 9px; color: var(--gold); }
.empty { color: #6b789f; font-size: 26px; text-align: center; padding: 50px 20px; }

/* ---------- shop / dialogs ---------- */
.modal-center {
  position: absolute; inset: 0; display: flex; align-items: center; justify-content: center; z-index: 40;
  background: rgba(3,5,12,.72); backdrop-filter: blur(2px);
}
.modal {
  width: min(620px, 88%);
  background: linear-gradient(180deg, #182046, #0c1124);
  border: 3px solid #e8d9a0;
  border-radius: 14px;
  box-shadow: 0 0 0 3px #141a33, 0 18px 50px rgba(0,0,0,.8);
  padding: 20px 22px;
}
.modal h3 { font-family: 'PixelTitle'; font-size: 13px; color: var(--gold); margin: 0 0 10px; letter-spacing: .5px; }
.modal p { font-size: 25px; color: #dce3f7; margin: 0 0 18px; line-height: 1.1; }
